INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('7c61db8f-303e-4621-83e3-09bac050ac36', 'a1a1a1a1-3030-4000-8000-000000000001', 18, 'Dia 18 — Disciplina', 'Semana 3: Reconstruir', '{"pch": "Disciplino o meu corpo\u2026 Sem disciplina, o prop\u00f3sito vira apenas desejo.", "verse": "1Cor 9,27", "lectio": "Leia 1Cor 9,24-27. Paulo corria para vencer.", "practice": "Escolha 1 h\u00e1bito pequeno e pratique por 7 dias consecutivos.", "question": "Em que \u00e1rea da sua vida falta disciplina?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;